def split_prices(digits, k, cap):
    width = len(str(cap))
    out = []
    parts = []

    def place(pos):
        left, rest = k - len(parts), len(digits) - pos
        if left == 0:
            if rest == 0:
                out.append(parts[:])
            return
        if rest < left or rest > left * width:
            return
        if digits[pos] == '0':
            return
        for end in range(pos + 1, min(pos + width, len(digits)) + 1):
            price = int(digits[pos:end])
            if price > cap:
                break
            parts.append(price)
            place(end)
            parts.pop()

    place(0)
    return out
